"""Contoh dan tindak lanjut mandiri; tidak menyalin butir gerbang atau bank penilaian."""
from math import sqrt,sin,cos,radians
LABELS=['Apa yang ditanyakan','Formulasi yang digunakan','Informasi distraktor (tidak diperlukan)','Identifikasi data','Substitusi nilai ke formula','Penyelesaian','Kesimpulan jawaban']
CONTEXT={
'f-mek-1-pra':('robot pemetaan ruang','gerobak sensor di bengkel'),
'f-mek-2':('troli pengantar alat','kereta ukur lintasan'),
'f-mek-1a':('peralatan latihan di rel udara','kendaraan uji laboratorium'),
'f-mek-1b':('perangkat penyangga pameran','rangka peraga laboratorium'),
'f-use-1-pra':('pengantaran kotak instrumen','pemindahan peralatan studio'),
'f-use-1':('jalur pengiriman sampel','lintasan uji kemasan')}
def make(slug,concept,index,stage,variant=0):
 kind=concept['lab']['kind'];n=index*4+variant+{'concept':1,'guided':21,'followup':41,'transfer':61}.get(stage,1);m=2+n%4;F=20+2*n;s=2+n%3;tag={'concept':'Analisis contoh','guided':'Contoh terbimbing','followup':'Perbaikan terarah','transfer':'Tantangan lintas konsep'}.get(stage,stage)
 scene=CONTEXT[slug][n%2];prefix=f'{tag} · {scene}, kasus {index+1}.{variant+1}. '
 label='Jawaban';unit='';diagram=None;extra='Nomor kasus hanya penanda kegiatan, tidak masuk perhitungan.'
 if kind=='vector':
  ax=6+n;bx=-2-n;by=3+n;ans=sqrt(16+by*by);label='Besar perpindahan';unit='m';prompt=f'Sensor menempuh A=({ax}, 0) m, kemudian B=({bx}, {by}) m. Timur +x dan utara +y. Tentukan besar perpindahan langsung serta kuadran arahnya.';form='Rx=Ax+Bx; Ry=Ay+By; R=√(Rx²+Ry²).';data=f'A=({ax},0) m, B=({bx},{by}) m; satuan kedua sumbu sama.';sub=f'Rx={ax}+({bx})=4; Ry={by}; R=√(4²+{by}²).';process=f'R=√{16+by*by}={ans:.3f} m. Rx dan Ry positif sehingga arah di kuadran I, bukan sepanjang seluruh ruas.';diagram={'kind':'vector','params':{'ax':ax,'ay':0,'bx':bx,'by':by}}
 elif kind=='components':
  ans=F*.6;label='Komponen mendatar';unit='N';prompt=f'Tali penarik memberikan gaya {F} N, membentuk sudut 37° dari arah vertikal ke kanan. Gunakan sin 37°=0,6 dan cos 37°=0,8. Berapa komponen mendatarnya?';form='Untuk sudut φ dari vertikal: Fx=F sin φ; Fy=F cos φ.';data=f'F={F} N, φ=37° dari +y, sin φ=0,6; kanan positif.';sub=f'Fx={F}×0,6.';process=f'Fx={ans:g} N dan Fy={F*.8:g} N. Kedua komponen membentuk kembali besar F; tidak dijumlah sebagai dua gaya tambahan.';diagram={'kind':'components','params':{'F':F,'theta':53.130102,'ref':'y'}}
 elif kind=='incline':
  W=10*m;ans=W*.5;label='Komponen berat sejajar';unit='N';prompt=f'Kotak dengan berat {W} N berada pada papan 30° terhadap mendatar. Tentukan besar komponen berat sepanjang papan; sin 30°=0,5. Jelaskan mengapa angka ini belum tentu gaya netonya.';form='W∥=W sin θ; resultan sepanjang bidang harus memasukkan semua gaya yang benar-benar bekerja.';data=f'W={W} N, θ=30°, sin θ=0,5; sumbu positif menuruni bidang.';sub=f'W∥={W}×0,5.';process=f'Komponen sejajar={ans:g} N. Komponen ini hanya bagian berat; tarikan atau gesekan lain harus dimasukkan bila ada. Berat tetap vertikal.';diagram={'kind':'incline','params':{'W':W,'theta':30}}
 elif kind=='motion':
  balanced=concept['id']=='n1';left=F if balanced else 8+n;net=F-left;ans=net/m;label='Percepatan bertanda';unit='m/s²';prompt=f'Benda bermassa {m} kg mula-mula melaju ke kanan 2 m/s. Tarikan kanan {F} N dan hambatan kiri {left} N bekerja mendatar; berat dan normal seimbang. Berapa percepatan bertandanya dan bagaimana kelajuannya berubah?';form='ΣFx=Fkanan−Fkiri; ax=ΣFx/m. Arah v sesaat dibedakan dari arah a.';data=f'm={m} kg; Fkanan={F} N; Fkiri={left} N; v₀=+2 m/s; kanan positif.';sub=f'ax=({F}−{left})/{m}.';process=f'Gaya neto {net} N memberi a={ans:.3f} m/s². '+('Kecepatan tetap +2 m/s karena a=0; bergerak tidak memerlukan resultan tak nol.' if balanced else 'Karena v awal dan a ke kanan, kelajuan bertambah. Setiap panah gaya harus mempunyai pemberi interaksi, bukan berasal dari gerak itu sendiri.');diagram={'kind':'motion','params':{'right':F,'left':left,'m':m,'v0':2,'t':2}}
 elif kind=='reaction':
  ma=20+n;mb=40+n;ans=F/mb;label='Percepatan benda kanan';unit='m/s²';prompt=f'Dua papan beroda mula-mula diam, dengan massa total kiri {ma} kg dan kanan {mb} kg. Interaksi dorong memberikan gaya {F} N pada masing-masing, berlawanan arah; rel licin. Tentukan besar percepatan papan kanan dan jelaskan mengapa kedua gaya tidak saling meniadakan.';form='Pasangan interaksi: Fkiri=−Fkanan pada dua benda berbeda; besar a=F/m.';data=f'F={F} N, mkanan={mb} kg, mkiri={ma} kg; tiap benda ditinjau sendiri.';sub=f'akanan={F}/{mb}.';process=f'Percepatan kanan={ans:.3f} m/s². Percepatan kiri={F/ma:.3f} m/s² dengan arah berlawanan. Gaya sama besar bekerja pada penerima berbeda, sehingga tidak dijumlah pada satu diagram.';diagram={'kind':'reaction','params':{'F':F,'m1':ma,'m2':mb,'t':2}}
 elif kind=='torque':
  r=round(.4+.01*n,2);ans=F*r*.5;label='Besar momen gaya';unit='N·m';prompt=f'Gaya {F} N bekerja pada batang pada jarak {r:g} m dari engsel. Sudut antara batang dan gaya 30°, sin 30°=0,5; gaya menarik sisi kanan batang ke atas. Tentukan momen dan arah kecenderungan putarnya.';form='τ=rF sin θ; lengan tegak lurus d=r sin θ.';data=f'F={F} N; r={r:g} m; θ=30°; arah putar positif berlawanan jarum jam.';sub=f'τ={r:g}×{F}×0,5.';process=f'Lengan d={r*.5:g} m dan τ={ans:g} N·m. Gaya melalui poros akan memberi momen nol meskipun besarnya tetap.';diagram={'kind':'torque','params':{'F':F,'r':r,'theta':30}}
 elif kind=='couple':
  d=round(.3+.005*n,3);ans=F*d;label='Besar momen pasangan';unit='N·m';prompt=f'Dua gaya sejajar sama besar {F} N bekerja berlawanan arah. Jarak tegak lurus antargaris kerjanya {d:g} m. Nilai resultan gaya dan momen pasangannya; apakah resultan nol cukup untuk menyatakan benda tidak berputar?';form='ΣF=0 untuk pasangan gaya; besar momen pasangan τ=F d.';data=f'F={F} N pada tiap gaya dan d={d:g} m antargaris kerja, bukan jarak ke salah satu poros.';sub=f'τ={F}×{d:g}.';process=f'Resultan gaya nol, tetapi momen={ans:g} N·m. Karena momen tidak nol, syarat setimbang rotasi belum terpenuhi.';diagram={'kind':'couple','params':{'F':F,'d':d}}
 elif kind=='cable':
  W=60+10*n;frac=.5;ans=W;label='Tegangan kabel';unit='N';prompt=f'Batang horizontal bermassa diabaikan berengsel di kiri. Beban {W} N berada di tengah batang panjang 2 m. Kabel dari ujung kanan membentuk sudut 30° terhadap batang; sin 30°=0,5. Sistem setimbang. Tentukan tegangan kabel dengan memilih poros yang menghilangkan momen reaksi engsel.';form='Στengsel=0: T sin θ·L=W·(L/2), sehingga T=W/(2 sin θ).';data=f'W={W} N; L=2 m; letak beban L/2=1 m; θ=30°.';sub=f'T×0,5×2={W}×1; T={W}/1.';process=f'T={ans:g} N. Komponen vertikal T adalah {W/2:g} N; sisa gaya vertikal ditopang engsel. Tegangan bukan otomatis sama dengan komponen vertikalnya.';diagram={'kind':'cable','params':{'W':W,'theta':30,'fraction':frac,'L':2}}
 elif kind=='work':
  ans=F*s*.5;label='Usaha gaya tarik';unit='J';prompt=f'Kotak instrumen bergeser mendatar {s} m sementara tali memberi gaya tetap {F} N pada 60° terhadap perpindahan. Gunakan cos 60°=0,5. Tentukan usaha gaya tali; bedakan dari usaha neto jika ada gaya lain.';form='Wgaya=F s cos θ, dengan θ sudut antara gaya dan perpindahan.';data=f'F={F} N, s={s} m, θ=60°, cos θ=0,5.';sub=f'W={F}×{s}×0,5.';process=f'W={ans:g} J, positif karena komponen gaya searah perpindahan. Komponen tegak lurus tidak memindahkan energi lewat perpindahan mendatar ini.';diagram={'kind':'work','params':{'F':F,'s':s,'theta':60}}
 elif kind=='kinetic':
  distance=round(6+.4*n,1);v=distance/2;ans=.5*m*v*v;label='Energi kinetik';unit='J';prompt=f'Sampel bermassa {m} kg bergerak konstan sejauh {distance} m dalam 2 s di jalur mendatar. Tentukan energi kinetik translasi sampel; angka jarak belum dapat langsung dipakai sebagai kelajuan.';form='v=s/t; Ek=½mv².';data=f'm={m} kg; s={distance} m; t=2 s; gerak konstan.';sub=f'v={distance}/2={v:g} m/s; Ek=½×{m}×{v:g}².';process=f'Ek={ans:g} J. Periksa satuan kg·m²/s²=J; massa linear tetapi kelajuan dikuadratkan.';diagram={'kind':'kinetic','params':{'m':m,'v':v}}
 elif kind=='potential':
  h=round(1.2+.02*n,2);ref=.4;ans=m*10*(h-ref);label='Energi potensial terhadap meja';unit='J';prompt=f'Sampel {m} kg berada {h:g} m di atas lantai. Meja {ref:g} m di atas lantai dipilih sebagai acuan energi potensial nol. Dengan g=10 m/s², tentukan Ep terhadap meja dan bandingkan tandanya dengan keadaan sampel di bawah meja.';form='Ep=mg(hbenda−hacuan).';data=f'm={m} kg; hbenda={h:g} m; hacuan={ref:g} m; g=10 m/s².';sub=f'Ep={m}×10×({h:g}−{ref:g}).';process=f'Tinggi relatif={h-ref:g} m, sehingga Ep={ans:g} J. Bila benda di bawah acuan, Ep negatif tanpa menyatakan energi total sistem harus negatif.';diagram={'kind':'potential','params':{'m':m,'h':h,'ref':ref}}
 elif kind=='workenergy':
  v=round(4+.05*n,2);force=round(2+.02*n,2);d=2;K=.5*m*v*v;ans=K-force*d;label='Energi kinetik akhir';unit='J';prompt=f'Kotak {m} kg memasuki jalur mendatar dengan laju {v} m/s. Gaya neto tetap {force} N melawan gerak sepanjang {d} m. Tentukan energi kinetik akhirnya dan periksa bahwa benda belum berhenti sebelum jarak itu.';form='Ekakhir=Ekawal+Wneto=½mv₀²−F s; jarak berhenti Ekawal/F.';data=f'm={m} kg, v₀={v} m/s, Fneto berlawanan gerak={force} N, s={d} m.';sub=f'Ekakhir=½×{m}×{v}²−{force}×{d}.';process=f'Ekawal={K:g} J, usaha={-force*d:g} J; Ekakhir={ans:g} J>0. Jarak berhenti={K/force:.3f} m>{d} m, sehingga perhitungan berlaku.';diagram={'kind':'workenergy','params':{'m':m,'v0':v,'F':-force,'s':d}}
 else:
  h0=round(1.8+.03*n,2);h=.5;mu=.1 if concept['id']!='lintasan-ideal' else 0;d=2;ans=sqrt(20*(h0-h-mu*d));label='Kelajuan di tujuan';unit='m/s';prompt=f'Sampel dilepas diam dari tinggi {h0:g} m, turun licin, melewati segmen mendatar {d} m dengan μk={mu:g}, lalu naik licin ke tujuan {h:g} m. Semua tinggi dari acuan yang sama; g=10 m/s² dan benda dianggap partikel. Tentukan laju tujuan dan kelayakan mencapai titik itu.';form='mgh₀=½mv²+mgh+μmgd; v²=2g(h₀−h−μd).';data=f'v₀=0; h₀={h0:g} m; h={h:g} m; d={d} m; μ={mu:g}; g=10 m/s².';sub=f'v²=20×({h0:g}−{h:g}−{mu:g}×{d}).';process=f'Sisa tinggi energi={h0-h-mu*d:g} m>0, sehingga v={ans:.3f} m/s dan tujuan terjangkau. Massa tercoret; energi internal segmen kasar tetap dicatat dalam energi total.';diagram={'kind':'energy','params':{'m':m,'h0':h0,'h':h,'mu':mu,'s':d,'mode':'friction'if mu else'ideal','shape':'ramp','v0':0}}
 conclusion=f'{label} = {ans:.3f} {unit}. '+('Arah dan acuan mengikuti model pada stimulus.'if kind not in ('energy','workenergy')else'Jawaban hanya berlaku pada lintasan dan gaya yang diasumsikan.')
 values=[label+' beserta makna hasil pada kasus ini.',form,extra,data,sub,process,conclusion]
 return {'id':f'unik-{slug}-{concept["id"]}-{stage}-{variant}','kind':'num','indicator':concept['id'],'prompt':prefix+prompt,'label':label,'unit':unit,'answer':ans,'tol':.03,'level':'C3','seconds':120,'diagram':diagram,'steps':[a+': '+b for a,b in zip(LABELS,values)],'explain':process+' '+conclusion}
